def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections = {}
    current_section = None
    default_section = {}

    def add_key(key, value):
        if current_section is not None:
            if key in sections.get(current_section, {}):
                sections[current_section][key] = value
            else:
                sections[current_section][key] = value
        else:
            default_section[key] = value

    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1].strip()
            sections[current_section] = {}
        elif line.startswith('#') or line.startswith(';'):
            continue
        else:
            parts = line.split('=', 1)
            if len(parts) == 1:
                parts = parts[0].split(':', 1)
            key = parts[0].strip().lower()
            value =''.join(parts[1:]).strip()

            if value.startswith(('"', "'") and value.endswith(('"', "'")):
                value = value[1:-1]  

            if value:
                add_key(key, value.strip())

    for section, data in sections.items():
        for key, value in data.items():
            if '${' in value:

                def resolve_key(key):
                    key = key.strip()
                    if key.startswith("${") and key.endswith("}"):
                        key = key[2:-1]
                    if key.count(':') == 1:
                        section_name, key = key.split(':')
                        try:
                            return sections.get(section_name, {})[key]
                        except KeyError:
                            raise KeyError(f"{{ {key} }}")
                    else:
                        if key in sections.get(section, {}):
                            return sections.get(section, {})[key]
                        elif key in default_section:
                            return default_section[key]
                    raise KeyError(f"{{ {key} }}")



                while '${' in value: 
                    value = value.replace(key, resolve_key(key))

                add_key(key, value)

    return sections



