def parse_duration(s: str) =
    s = s.strip().lower()
    if not s:
       raise ValueError("Empty/blank string not allowed.")
    parts = s.split()
    if len(parts) == 0 or len(parts) > 3:
        raise ValueError("Invalid duration format.")

    total_seconds = 0
    seen_units = set()

    for part in parts:
        if len(part) < 2: 
            raise ValueError("Invalid duration format (number without unit).")
        number = part[:-1]
        unit = part[-1]

        if not number.isdigit():
            raise ValueError("Invalid duration format (non-digit number).")

        if unit not in ('h', 'm', 's'):
            raise ValueError("Unknown unit")
        if unit in seen_units:
            raise ValueError("Repeated unit.")
        seen_units.add(unit)

        if unit == 'h':
            total_seconds += int(number) * 3600
        elif unit == 'm':
            total_seconds += int(number) * 60
        else:
            total_seconds += int(number)

    return total_seconds   
